<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Personal Expense Tracker</title>
<style>
body{font-family:sans-serif;margin:20px;background:#f9f9f9}
h1{text-align:center}
form, .filters, .summary{margin-bottom:20px}
label{display:inline-block;width:80px;font-weight:bold}
input[type="number"], input[type="date"], select{width:150px;padding:4px;margin-right:10px}
button{padding:5px 10px}
#form-error{color:red;min-height:1.2em}
table{width:100%;border-collapse:collapse;background:#fff}
th,td{text-align:left;padding:8px;border-bottom:1px solid #ddd}
.exp-del{background:#e74c3c;color:white;border:none;padding:4px 6px;font-size:0.9em;cursor:pointer}
.exp-del:hover{background:#c0392b}
.cat-total{font-weight:bold;margin-right:15px}
</style>
</head>
<body>

<h1>Expense Tracker</h1>

<form id="expense-form">
    <label for="amount">Amount:</label>
    <input type="number" step="0.01" id="amount" required><br>
    <label for="category">Category:</label>
    <select id="category">
        <option value="groceries">Groceries</option>
        <option value="transport">Transport</option>
        <option value="bills">Bills</option>
        <option value="fun">Fun</option>
    </select><br>
    <label for="date">Date:</label>
    <input type="date" id="date" required><br>
    <label for="note">Note:</label>
    <input type="text" id="note"><br>
    <button type="submit" id="add-expense">Add Expense</button>
    <div id="form-error"></div>
</form>

<div class="filters">
    <label for="filter-category">Filter by Category:</label>
    <select id="filter-category">
        <option value="all">All</option>
        <option value="groceries">Groceries</option>
        <option value="transport">Transport</option>
        <option value="bills">Bills</option>
        <option value="fun">Fun</option>
    </select>

    <label for="filter-from">From:</label>
    <input type="date" id="filter-from">

    <label for="filter-to">To:</label>
    <input type="date" id="filter-to">
</div>

<table>
<thead><tr><th>Amount</th><th>Category</th><th>Date</th><th>Note</th><th></th></tr></thead>
<tbody id="expense-list"></tbody>
</table>

<div class="summary">
    <strong>Total: $<span id="total">0.00</span></strong>
    <div id="category-summaries">
        <span class="cat-total" data-cat="groceries">Groceries: $0.00</span>
        <span class="cat-total" data-cat="transport">Transport: $0.00</span>
        <span class="cat-total" data-cat="bills">Bills: $0.00</span>
        <span class="cat-total" data-cat="fun">Fun: $0.00</span>
    </div>
</div>

<script>
(() => {
const form = document.getElementById('expense-form');
const amountInput = document.getElementById('amount');
const categorySelect = document.getElementById('category');
const dateInput = document.getElementById('date');
const noteInput = document.getElementById('note');
const errorDiv = document.getElementById('form-error');

const expenseList = document.getElementById('expense-list');
const totalSpan = document.getElementById('total');
const catTotals = document.querySelectorAll('.cat-total');

const filterCategory = document.getElementById('filter-category');
const filterFrom = document.getElementById('filter-from');
const filterTo = document.getElementById('filter-to');

let expenses = [];

// Load from localStorage
function loadExpenses() {
    const stored = localStorage.getItem('expenses');
    if (stored) {
        try { expenses = JSON.parse(stored); } catch(e){ expenses=[]; }
    }
}
loadExpenses();
renderAll();

// Save to localStorage
function saveExpenses() {
    localStorage.setItem('expenses', JSON.stringify(expenses));
}

// Render a single expense row at the top
function renderExpense(exp, prepend=true) {
    const tr = document.createElement('tr');
    tr.className='expense';
    tr.dataset.cat=exp.category;
    tr.dataset.date=exp.date;

    tr.innerHTML = `
        <td>$${Number(exp.amount).toFixed(2)}</td>
        <td>${capitalize(exp.category)}</td>
        <td>${exp.date}</td>
        <td>${escapeHtml(exp.note||'')}</td>
        <td><button class="exp-del">Delete</button></td>
    `;
    tr.querySelector('.exp-del').addEventListener('click', () => {
        deleteExpense(exp);
    });

    if(prepend) expenseList.prepend(tr);
    else expenseList.appendChild(tr);
}

// Render all expenses (used on load)
function renderAll() {
    expenseList.innerHTML='';
    // newest first: assume last added is newest
    for(let i=expenses.length-1;i>=0;--i){
        renderExpense(expenses[i], false);
    }
    applyFilters();
}

// Capitalize first letter
function capitalize(s){return s.charAt(0).toUpperCase()+s.slice(1);}

// Escape HTML
function escapeHtml(str){
    return str.replace(/[&<>"']/g, function(m){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&#34;',"'":'&#39;'}[m];});
}

// Delete expense
function deleteExpense(exp) {
    const idx = expenses.indexOf(exp);
    if(idx>-1){
        expenses.splice(idx,1);
        saveExpenses();
        renderAll();
    }
}

// Add new expense
form.addEventListener('submit', e=>{
    e.preventDefault();
    const amt = parseFloat(amountInput.value);
    const cat = categorySelect.value;
    const date = dateInput.value;
    const note = noteInput.value.trim();

    // Validation
    if(isNaN(amt) || amt<=0){
        errorDiv.textContent='Amount must be a positive number.';
        return;
    }
    if(!date){
        errorDiv.textContent='Date is required.';
        return;
    }

    // Valid
    errorDiv.textContent='';
    const newExp = {amount:amt, category:cat, date, note};
    expenses.push(newExp);
    saveExpenses();
    renderExpense(newExp);
    applyFilters();

    amountInput.value='';
});

// Filters
[filterCategory, filterFrom, filterTo].forEach(el=>{
    el.addEventListener('change', applyFilters);
});

function applyFilters(){
    const cat = filterCategory.value;
    const from = filterFrom.value;
    const to = filterTo.value;

    let visibleSum=0;
    const catSums={groceries:0, transport:0, bills:0, fun:0};

    Array.from(expenseList.children).forEach(row=>{
        const rowCat=row.dataset.cat;
        const rowDate=row.dataset.date;

        let show=true;
        if(cat!=='all' && rowCat!==cat) show=false;
        if(from && rowDate<from) show=false;
        if(to && rowDate>to) show=false;

        row.style.display=show?'':'none';
        if(show){
            const amt=parseFloat(row.children[0].textContent.replace('$',''));
            visibleSum+=amt;
            catSums[rowCat]+=amt;
        }
    });

    totalSpan.textContent=visibleSum.toFixed(2);
    catTotals.forEach(span=>{
        const c=span.dataset.cat;
        span.textContent=`${capitalize(c)}: $${catSums[c].toFixed(2)}`;
    });
}
})();
</script>
</body>
</html>
